function numPrimeArrangements(n) {
  const MOD = 1e9 + 7;
  const isPrime = new Array(n + 1).fill(true);
  isPrime[0] = false;
  isPrime[1] = false;
  for (let p = 2; p * p <= n; p++) {
    if (!isPrime[p]) continue;
    for (let multiple = p * p; multiple <= n; multiple += p) {
      isPrime[multiple] = false;
    }
  }

  let primes = 0;
  for (let value = 2; value <= n; value++) {
    if (isPrime[value]) primes++;
  }
  const others = n - primes;

  let answer = 1;
  for (let k = 2; k <= primes; k++) {
    answer = (answer * k) % MOD;
  }
  for (let k = 2; k <= others; k++) {
    answer = (answer * k) % MOD;
  }
  return answer;
}

