    const used = new Array(n + 1).fill(false);
    const place = (pos) => {
      if (pos > n) return 1;
      let total = 0;
      for (let v = 1; v <= n; v++) {
        if (used[v] || prime(v) !== prime(pos)) continue;
        used[v] = true;
        total += place(pos + 1);
        used[v] = false;
